// Inbox Framework only. Protected service supplies canonical JSON; XML is self-describing for recovery.
using System;
using System.Linq;
using System.Text;
using System.Xml;
using System.Web.Script.Serialization;
using Aict.Enforcement;
namespace AictServicePolicyLab {
    public sealed class BetaAllow {public string Id="";public PolicyTarget[] Applications=new PolicyTarget[0];}
    public sealed class BetaPlan {public PolicyTarget[] Denied=new PolicyTarget[0];public BetaAllow[] Whitelists=new BetaAllow[0];}
    static class BetaPolicyXml {
        internal const string Empty="{\"denied\":[],\"whitelists\":[]}";
        static readonly JavaScriptSerializer Json=new JavaScriptSerializer {MaxJsonLength=524288};
        internal static BetaPlan Parse(string raw){if(raw.Length>262144)throw new ArgumentException("Plan too large");var p=Json.Deserialize<BetaPlan>(raw);if(p.Denied==null || p.Whitelists==null || p.Denied.Length>64 || p.Whitelists.Length>8)throw new ArgumentException("Invalid plan dimensions");foreach(var a in p.Denied)a.Validate();if(p.Denied.Select(a=>a.Id).Distinct().Count()!=p.Denied.Length)throw new ArgumentException("Duplicate denied identities");foreach(var g in p.Whitelists){Guid id;if(!Guid.TryParseExact(g.Id,"N",out id) || g.Applications==null || g.Applications.Length>64)throw new ArgumentException("Invalid allow group");foreach(var a in g.Applications)a.Validate();if(g.Applications.Select(a=>a.Id).Distinct().Count()!=g.Applications.Length)throw new ArgumentException("Duplicate allowed identities");}if(p.Whitelists.Select(g=>g.Id).Distinct().Count()!=p.Whitelists.Length)throw new ArgumentException("Duplicate allow groups");return p;}
        static XmlElement Element(XmlElement parent,string name){var x=parent.OwnerDocument.CreateElement(name);parent.AppendChild(x);return x;}
        static void Attr(XmlElement x,string k,string v){x.SetAttribute(k,v);}
        static void Hash(XmlElement parent,PolicyTarget app){var h=Element(parent,"FileHash");Attr(h,"Type","SHA256");Attr(h,"Data",app.SipHash);Attr(h,"SourceFileName",app.FileName);Attr(h,"SourceFileLength",app.Size.ToString(global::System.Globalization.CultureInfo.InvariantCulture));}
        internal static string Exe(string run,string sid,string root,string raw){
            new global::System.Security.Principal.SecurityIdentifier(sid);var p=Parse(raw);if(p.Denied.Length+p.Whitelists.Length==0)throw new ArgumentException("Empty collection");
            var doc=new XmlDocument {XmlResolver=null};var collection=doc.CreateElement("RuleCollection");doc.AppendChild(collection);Attr(collection,"Type","Exe");Attr(collection,"EnforcementMode","Enabled");
            string header=Convert.ToBase64String(Encoding.UTF8.GetBytes(raw));int count=(header.Length+959)/960;
            for(int i=0;i<count;i++){var allow=Element(collection,"FilePathRule");Attr(allow,"Id",AppLockerXml.RuleId(run,"beta-header/"+i));Attr(allow,"Name","AICT Beta "+run+" header "+i.ToString("D3"));Attr(allow,"Description",header.Substring(i*960,Math.Min(960,header.Length-i*960)));Attr(allow,"UserOrGroupSid","S-1-1-0");Attr(allow,"Action","Allow");Attr(Element(Element(allow,"Conditions"),"FilePathCondition"),"Path","*");}
            foreach(var app in p.Denied.OrderBy(a=>a.Id,StringComparer.Ordinal)){var deny=Element(collection,"FileHashRule");Attr(deny,"Id",AppLockerXml.RuleId(run,"beta-deny/"+app.Id));Attr(deny,"Name","AICT selected application");Attr(deny,"Description","Owned beta policy");Attr(deny,"UserOrGroupSid",sid);Attr(deny,"Action","Deny");Hash(Element(Element(deny,"Conditions"),"FileHashCondition"),app);}
            foreach(var group in p.Whitelists.OrderBy(g=>g.Id,StringComparer.Ordinal)){var deny=Element(collection,"FilePathRule");Attr(deny,"Id",AppLockerXml.RuleId(run,"beta-whitelist/"+group.Id));Attr(deny,"Name","AICT application allowlist");Attr(deny,"Description","Owned beta policy");Attr(deny,"UserOrGroupSid",sid);Attr(deny,"Action","Deny");Attr(Element(Element(deny,"Conditions"),"FilePathCondition"),"Path","*");var exceptions=Element(deny,"Exceptions");Attr(Element(exceptions,"FilePathCondition"),"Path",global::System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"*"));Attr(Element(exceptions,"FilePathCondition"),"Path",global::System.IO.Path.Combine(root,"*"));foreach(var app in group.Applications.OrderBy(a=>a.Id,StringComparer.Ordinal))Hash(Element(exceptions,"FileHashCondition"),app);}
            return doc.OuterXml;
        }
        internal static XmlDocument ParseXml(string xml){if(xml.Length>1048576)throw new InvalidOperationException("Oversized beta XML");if(!xml.TrimStart().StartsWith("<",StringComparison.Ordinal))xml=global::System.Net.WebUtility.HtmlDecode(xml);var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new global::System.IO.StringReader(xml),new XmlReaderSettings{XmlResolver=null,DtdProcessing=DtdProcessing.Prohibit,MaxCharactersInDocument=1048576}))doc.Load(reader);return doc;}
        static bool Same(XmlElement a,XmlElement b){if(a.Name!=b.Name || a.Attributes.Count!=b.Attributes.Count)return false;foreach(XmlAttribute attr in b.Attributes)if(a.GetAttribute(attr.Name)!=attr.Value)return false;foreach(XmlNode n in a.ChildNodes)if(!(n is XmlElement) && !string.IsNullOrWhiteSpace(n.Value))return false;var aa=a.ChildNodes.OfType<XmlElement>().ToArray();var bb=b.ChildNodes.OfType<XmlElement>().ToArray();return aa.Length==bb.Length && aa.Select((node,i)=>Same(node,bb[i])).All(v=>v);}
        internal static string ReadOwned(string xml,string run,string root,out string sid){var doc=ParseXml(xml);var headers=doc.SelectNodes("/RuleCollection/FilePathRule[@Action='Allow']");if(headers==null || headers.Count<1 || headers.Count>400)throw new InvalidOperationException("Missing owned headers");var header=new StringBuilder();foreach(XmlElement h in headers){if(h.GetAttribute("Description").Length>1024)throw new InvalidOperationException("Description exceeds AppLocker schema");header.Append(h.GetAttribute("Description"));}string raw=Encoding.UTF8.GetString(Convert.FromBase64String(header.ToString()));Parse(raw);var deny=doc.SelectSingleNode("/RuleCollection/*[@Action='Deny']") as XmlElement;if(deny==null)throw new InvalidOperationException("Missing owned denial");sid=deny.GetAttribute("UserOrGroupSid");if(!Same(doc.DocumentElement,ParseXml(Exe(run,sid,root,raw)).DocumentElement))throw new InvalidOperationException("Owned policy shape changed; left untouched");return raw;}
    }
}
